import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([10, len(columns)] + [len(row) for row in rows])

    used = set(columns)
    while len(columns) < width:
        index = len(columns) + 1
        name = "Column " + str(index)
        suffix = 2
        while name in used:
            name = "Column " + str(index) + " (" + str(suffix) + ")"
            suffix += 1
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
